/* 0x0204ce30 (0x1b4 bytes) ScriptThread_runEvent (Ghidra: FUN_0204ce30)
 * file: name */
/* Runs the commands of frame's event from the one after cmdIndex. A command runs when the event's
 * state is one of its states (bits 16..24; with none, only when the event has state 0, or the
 * states the frame asks for) and the way the tile was entered is one of its ways. */
int ScriptThread_runEvent( ScriptThread *self, ScriptFrame *frame ) {
	Render	*render = self->app->render;
	u32		event = frame->event;
	int		state = EVENT_STATE( event );
	int		end = EVENT_COUNT( event ) * 3, i;
	u32		states;
	Command	*cmds;
	int		ranAny = 0;

	Dbg_printf( "script#%d.%d executing from %d", self->id, (int)( frame - self->frames ), frame->cmdIndex );
	if ( ( event & 0x80000000 ) && ( frame->flags & 0x400 ) ) {
		return SCRIPT_NOT_RUN;
	}
	states = state == 0 ? 0 : 0x10000u << ( state - 1 );
	if ( frame->flags & 0x1ff0000 ) {
		states |= frame->flags & 0x1ff0000;
	}
	cmds = &render->commands[EVENT_FIRST( event )];
	/* (i walks the commands' words, 3 a command) */
	for ( i = frame->cmdIndex * 3; i < end; i += 3 ) {
		Command	*c = &cmds[i / 3];
		u32		f = c->flags;
		int		r;

		if ( states == 0 ? ( f & 0x1ff0000 ) != 0 : ( f & states ) == 0 ) {
			continue;
		}
		if ( !( frame->flags & f ) ) {
			continue;
		}
		c->flags |= 0x100;
		r = ScriptThread_executeEvent( self, frame, c->op, c->arg, f );
		if ( r == SCRIPT_NOT_RUN ) {
			continue;
		}
		if ( r != SCRIPT_ABORT && ( f & 0x200 ) ) {
			c->flags = 0;		/* once */
		}
		if ( r == SCRIPT_PAUSED ) {
			frame->cmdIndex = (u8)( i / 3 );
			return SCRIPT_PAUSED;
		}
		if ( r == SCRIPT_ABORT ) {
			return SCRIPT_ABORT;
		}
		if ( r == SCRIPT_RESTART ) {
			i = 0;				/* (then + 3: the second command, as the BREW game) */
			frame->cmdIndex = 0;
		}
		ranAny = 1;
	}
	return ranAny;
}

/* 0x0204cfe4 (0xe0 bytes) ScriptThread_executeTile (Ghidra: FUN_0204cfe4)
 * file: name */
/* Runs the event of tile (tx, ty) entered the ways flags says; returns what ScriptThread_run did
 * (a tail call), else SCRIPT_NOT_RUN */
int ScriptThread_executeTile( ScriptThread *self, int tx, int ty, int flags, int nested ) {
	Game	*game = self->app->game;
	Render	*render;
	int		tile, ev;

	if ( game->scriptsDisabled || tx < 0 || tx >= MAP_TILES || ty < 0 || ty >= MAP_TILES ) {
		self->state = SCRIPT_NOT_RUN;
		return SCRIPT_NOT_RUN;
	}
	game->yieldFlag = 0;
	tile = tx + ty * MAP_TILES;
	render = self->app->render;
	if ( !( render->mapFlags[tile] & TILE_HAS_EVENT ) ) {
		Dbg_printf( "Warning: executeTile could not find script to execute at x:%d y:%d", tx, ty );
	} else {
		ev = Render_findTileEvent( render, tile );
		if ( ev != -1 ) {
			ScriptThread_pushFrame( self, self->app->render->tileEvents[ev], flags, nested );
			return ScriptThread_run( self );
		}
	}
	self->state = SCRIPT_NOT_RUN;
	return SCRIPT_NOT_RUN;
}

/* 0x0204d0c4 (0xfc bytes) ScriptThread_queueTile (Ghidra: FUN_0204d0c4)
 * file: name */
/* As executeTile, but the frame is only pushed, paused: the caller runs it later */
int ScriptThread_queueTile( ScriptThread *self, int tx, int ty, int flags, int nested ) {
	Game	*game = self->app->game;
	Render	*render;
	int		tile, ev;

	if ( game->scriptsDisabled || tx < 0 || tx >= MAP_TILES || ty < 0 || ty >= MAP_TILES ) {
		self->state = SCRIPT_NOT_RUN;
		return 0;
	}
	game->yieldFlag = 0;
	tile = tx + ty * MAP_TILES;
	render = self->app->render;
	if ( !( render->mapFlags[tile] & TILE_HAS_EVENT ) ) {
		Dbg_printf( "Warning: executeTile could not find script to execute at x:%d y:%d", tx, ty );
	} else {
		ev = Render_findTileEvent( render, tile );
		if ( ev != -1 ) {
			ScriptThread_pushFrame( self, self->app->render->tileEvents[ev], flags, nested );
			self->frames[self->numFrames - 1].frameFlags |= FRAME_PAUSED;
			return SCRIPT_PAUSED;
		}
	}
	self->state = SCRIPT_NOT_RUN;
	return 0;
}

/* 0x0204d1c0 (0x90 bytes) ScriptThread_pushFrame (Ghidra: FUN_0204d1c0)
 * file: name */
void ScriptThread_pushFrame( ScriptThread *self, u32 event, u32 flags, int nested ) {
	ScriptFrame *f;

	if ( self->numFrames == MAX_SCRIPT_STACK ) {
		App_fatal( app, "MAX_SCRIPT_STACK" );
		return;
	}
	Dbg_printf( "script#%d.%d allocating", self->id, self->numFrames, nested );
	f = &self->frames[self->numFrames++];
	f->cmdIndex = 0xff;
	f->frameFlags = 0;
	if ( nested ) {
		f->frameFlags |= FRAME_NESTED;
	}
	f->event = event;
	f->flags = flags;
}

/* 0x0204d250 (0x10c bytes) ScriptThread_run (Ghidra: FUN_0204d250)
 * file: name */
/* Runs (or resumes) the top frame. A finished frame is popped, and the frame below, if it was
 * paused for it, runs on. */
int ScriptThread_run( ScriptThread *self ) {
	int			top;
	ScriptFrame	*f;

	if ( self->numFrames == 0 ) {
		OS_DebugBreak();
	}
	top = self->numFrames - 1;
	f = &self->frames[top];
	f->cmdIndex++;
	self->state = (s8)ScriptThread_runEvent( self, f );
	if ( self->state == SCRIPT_PAUSED ) {
		Dbg_printf( "script#%d.%d paused", self->id, top );
		f->frameFlags |= FRAME_PAUSED;
		return SCRIPT_PAUSED;
	}
	Dbg_printf( "script#%d.%d finishing (%d)", self->id, top );
	self->numFrames--;
	if ( self->numFrames > 0 ) {
		ScriptFrame *below = &self->frames[self->numFrames - 1];
		if ( ( below->frameFlags & FRAME_PAUSED ) && !( below->frameFlags & FRAME_NO_RESUME ) ) {
			Dbg_printf( "script#%d.%d unpausing", self->id );
			below->frameFlags &= ~FRAME_PAUSED;
			self->state = (s8)ScriptThread_run( self );
		}
	}
	return self->state;
}

/* 0x0204d35c (0x14 bytes) ScriptThread_popFrame (Ghidra: FUN_0204d35c)
 * file: name */
void ScriptThread_popFrame( ScriptThread *self ) {
	if ( self->numFrames > 0 ) {
		self->numFrames--;
	}
}

/* 0x0204d370 (0x18 bytes) ScriptThread_init (Ghidra: FUN_0204d370)
 * file: name */
void ScriptThread_init( ScriptThread *self ) {
	self->numFrames = 0;
	self->waitUntil = 0;
	self->state = SCRIPT_PAUSED;
}

/* 0x0204d388 (0x5388 bytes) lowerWand (Ghidra: ScriptThread_executeEvent)
 * file: between two ScriptThread */
/* ScriptThread::executeEvent: runs one command of a tile event. op is the DS's opcode (the BREW
 * game's + 1 from 0x3a on, with new ones from 0x62 and 0x67), arg its argument, flags the
 * command's flags. Returns SCRIPT_NOT_RUN, SCRIPT_DONE, SCRIPT_PAUSED (the thread waits),
 * SCRIPT_ABORT (the event stops) or SCRIPT_RESTART.
 *
 * Every command first prints "script#%d.%d calling index %d: %s" with its EV_ name. Errors are
 * the game's: App_fatal for script mistakes, App_setErrorStr + the EDEBUG / EFAILED error with
 * the line in ScriptThread.cpp for missing entities. */

#define B0	( arg & 0xff )
#define B1	( ( arg >> 8 ) & 0xff )
#define B2	( ( arg >> 16 ) & 0xff )
#define B3	( arg >> 24 )
#define CALLING( name )	Dbg_printf( "script#%d.%d calling index %d: %s", self->id, (int)( frame - self->frames ), \
							frame->cmdIndex, name )

/* the weapon goes down for a dialog: the wand is put away */
static void lowerWand( Player *player ) {
	if ( player->weapons & 1 ) {
		if ( player->ce.weapon == 0 ) {
			player->prevWeapon = 0;
		} else {
			Player_selectWeapon( player, 0 );
		}
	}
}

int ScriptThread_executeEvent( ScriptThread *self, ScriptFrame *frame, int op, u32 arg, u32 flags ) {
	App		*app = self->app;
	Game	*game = app->game;
	Canvas	*canvas = app->canvas;
	Text	*text = app->text;
	Render	*render = app->render;
	Player	*player = app->player;
	Hud		*hud = app->hud;
	Sound	*sound = app->sound;
	int		r, i;

	switch ( op ) {
	case 0x01: {	/* EV_GOTO: the player to tile b0, b1, facing direction (arg >> 16) & 0x3ff (0xff: as is) */
		int dir = ( arg >> 16 ) & 0x3ff;
		CALLING( "EV_GOTO" );
		if ( game->snapMonsters ) {
			Game_snapAllMonsterSprites( game, 1 );
		}
		while ( game->combatMonsters ) {
			Game_removeFromCombat( game->combatMonsters );
		}
		Game_beginPlayerTurn( game );
		/* the tile left first */
		Game_executeTile( game, canvas->viewX >> 6, canvas->viewY >> 6, 0x04000400, 1 );
		Automap_visit( app->menuSystem, canvas->viewX >> 6, canvas->viewY >> 6 );
		Automap_visit( app->menuSystem, canvas->destX >> 6, canvas->destY >> 6 );
		canvas->destX = canvas->viewX = TILE_CENTER( B0 );
		canvas->destY = canvas->viewY = TILE_CENTER( B1 );
		if ( dir != 0xff ) {
			canvas->viewAngle = canvas->destAngle = Util_DirToAngle( dir );
			Canvas_finishRotation( canvas );
		}
		Player_FUN_0203f77c( player );
		Canvas_updateFacing( canvas );
		Canvas_FUN_0201a718( canvas );
		break;
	}

	case 0x02:		/* EV_CHANGEMAP: the map change the canvas does next (bit 30: shake first, bit 29: fade) */
		CALLING( "EV_CHANGEMAP" );
		game->pendingMapChange = arg;
		if ( arg & 0x40000000 ) {
			game->pendingMapChange = arg & ~0x40000000u;
			Canvas_startShake( canvas, 750, 2, 0 );
			Canvas_startFade( canvas, 1000, 2 );
		} else if ( arg & 0x20000000 ) {
			Canvas_startFade( canvas, 1000, 2 );
		} else {
			Canvas_startFade( canvas, 0, 2 );
		}
		Canvas_setState( canvas, CS_LOADING );
		canvas->changingMap = 1;
		return SCRIPT_ABORT;

	case 0x03:		/* EV_TRIGGER: the event of tile b0, b1 runs nested; bit 31: of a random tile of
					 * [b0, b1) x [b2, b3 & 0x7f) */
	case 0x4c: {	/* EV_TRIGGER in a thread of its own */
		int tx, ty;
		CALLING( "EV_TRIGGER" );
		if ( !( arg & 0x80000000 ) ) {
			tx = B0;
			ty = B1;
		} else {
			u32 rect = arg & 0x7fffffff;
			int x1 = ( rect >> 8 ) & 0xff, y0 = ( rect >> 16 ) & 0xff, y1 = (int)( rect >> 24 );
			tx = B0;
			if ( x1 != tx ) {
				tx += App_randomBelow( app, x1 - tx );
			}
			ty = y0;
			if ( y1 != y0 ) {
				ty += App_randomBelow( app, y1 - y0 );
			}
		}
		if ( op == 0x4c ) {
			ScriptThread_executeTile( Game_allocScriptThread( game ), tx, ty, (int)( flags & 0x2000000 ) | 0xf000, 0 );
		} else {
			u8 ff = frame->frameFlags;
			frame->frameFlags = ff | FRAME_NO_RESUME;
			r = ScriptThread_executeTile( self, tx, ty, (int)( flags & 0x2000000 ) | 0xf000, ff & FRAME_NESTED );
			frame->frameFlags &= ~FRAME_NO_RESUME;
			if ( r == SCRIPT_PAUSED ) {
				return SCRIPT_PAUSED;
			}
		}
		break;
	}

	case 0x04:		/* EV_MESSAGE: map string lo16; b2: 1 a cinematic's 2-line caption, 2 a message of kind 3 */
		CALLING( "EV_MESSAGE" );
		if ( game->skipping ) {
			break;
		}
		String_clear( &canvas->text, 0 );
		Text_getString( text, canvas->stringGroup, (s16)arg, &canvas->text );
		if ( canvas->state == CS_CAMERA ) {
			if ( B2 == 1 ) {
				String_clear( &hud->subtitle2, 0 );
				Text_wrapLines( text, &canvas->text, canvas->lineWidth, &hud->subtitle2, 2, 10, 0 );
			} else {
				String_clear( &hud->subtitle1, 0 );
				Text_wrap( text, &canvas->text, 9999, &hud->subtitle1 );
			}
		} else if ( B2 == 2 ) {
			Hud_addMessage( hud, &canvas->text, 3 );
		} else {
			if ( canvas->state == CS_CAMERA ) {
				hud->numSubtitles = 0;
			}
			Hud_addMessage( hud, &canvas->text, 0 );
		}
		break;

	case 0x05:		/* EV_PAIN: "Pain!" and arg damage */
		CALLING( "EV_PAIN" );
		Hud_gameMessage( hud, 0xcb, 0 );
		Player_hurtFeedback( player, 0 );
		Player_takeDamage( player, (int)arg, 0 );
		break;

	case 0x06:		/* EV_*LINE: Game_useDoor for line arg (6 use, 0xf open, 0x10 close, 0x11 move) */
	case 0x0f:
	case 0x10:
	case 0x11:
		CALLING( "EV_*LINE" );
		if ( (int)arg < 0 || (int)arg >= render->numLines ) {
			App_fatal( app, "EV_MOVELINE invalid line index %d", arg );
			return SCRIPT_NOT_RUN;
		}
		if ( !Game_useDoor( game, op, (int)arg, 1 ) ) {
			return SCRIPT_NOT_RUN;
		}
		break;

	case 0x07:		/* EV_SHOW: sprite lo16 shown with frame b2 at z b3; 0x67 also wakes its monster */
	case 0x67: {
		Sprite	*s = &render->sprites[arg & 0xffff];
		Entity	*e;
		CALLING( "EV_SHOW" );
		s->z = (s16)B3;
		s->info = ( s->info & ~( SPRITE_FRAME | SPRITE_HIDDEN ) ) | ( B2 << 8 );
		if ( ( s->z != 0x20 || B2 != 0 ) && s->ent ) {
			s->ent->info |= ENT_DIRTY;
		}
		if ( !s->ent ) {
			Dbg_printf( "making sprite %d visible at %d %d", s->info & 0xff, s->x >> 6, s->y >> 6 );
			break;
		}
		Dbg_printf( "making sprite %i visible at %d %d", s->ent->def->name, s->x >> 6, s->y >> 6 );
		/* whatever stands there dies */
		for ( i = 0; i < 2; i++ ) {
			e = Game_findEntityAt( game, s->x, s->y, 0x404 );
			if ( e ) {
				Dbg_printf( "TELEFRAG!" );
				Entity_kill( e, 1 );
			}
		}
		if ( s->ent->info & ENT_LINKED ) {
			Game_unlinkEntity( game, s->ent );
		}
		Game_linkEntity( game, s->ent, s->x >> 6, s->y >> 6 );
		e = s->ent;
		if ( op == 0x67 && e->def->eType == ETYPE_MONSTER && !( e->info & 0x400a0000 ) ) {
			e->info |= ENT_AGGRO;
			Game_activateEx( game, e, 1, 0 );
		}
		if ( e->def->eType == ETYPE_CORPSE && e->def->eSubType == 0xf ) {
			e->info = ( e->info & ~ENT_REMOVED ) | ENT_ALIVE;
		}
		break;
	}

	case 0x08: {	/* EV_DIALOG: map string (arg >> 16) in style b0 (1 the wand's, 2 a help with a title,
					 * 5..8 ...), flags b1 (4: the wand wants to talk, when it is in hand) */
		int style = B0, str = (s16)( arg >> 16 );
		CALLING( "EV_DIALOG" );
		if ( game->suppressDialog ) {
			return SCRIPT_DONE;
		}
		if ( ( B1 & 4 ) && player->ce.weapon != 0 ) {
			Player_setWandMood( player, 1 );
			player->wandChatStr = (int)( ( arg >> 16 ) & 0xffff );
			App_printf( app, "ScriptThread::executeEvent: wandDialogIndex %d", ( arg >> 16 ) & 0xffff );
			break;
		}
		if ( style >= 5 && style <= 8 ) {
			player->attacked = 0;
		}
		if ( style == 1 ) {
			Canvas_showDialog( canvas, self, canvas->stringGroup, str, 1, 1, 1 );
			lowerWand( player );
			Player_setWandMood( player, 0 );
			hud->wandChat = 0;
		} else if ( style == 2 ) {
			Canvas_addScriptHelp( canvas, canvas->stringGroup, str, self, 3 );
		} else {
			Canvas_showDialog( canvas, self, canvas->stringGroup, str, style, B1, 1 );
		}
		if ( style != 1 && style != 2 && style != 3 ) {
			lowerWand( player );
		}
		game->yieldFlag = 1;
		return SCRIPT_PAUSED;
	}

	case 0x09:		/* EV_GIVEMAP: the automap of the rectangle b3, b2, b1, b0 */
		CALLING( "EV_GIVEMAP" );
		Game_revealAutomapRect( game, B3, B2, B1, B0 );
		break;

	case 0x0a:		/* EV_PASSWORD: the combination is map string lo16, each character stored minus 'P' */
		CALLING( "EV_PASSWORD" );
		String_clear( &game->password, 0 );
		Text_getString( text, canvas->stringGroup, (s16)arg, &game->password );
		for ( i = 0; i < String_length( &game->password ); i = ( i + 1 ) & 0xff ) {
			String_setCharAt( &game->password, i, (s8)( String_charAt( &game->password, i ) + 0x50 ) );
		}
		String_clear( &canvas->text, 0 );
		Canvas_showChatDialog( canvas, self, &canvas->text );
		game->yieldFlag = 1;
		return SCRIPT_PAUSED;

	case 0x0b:		/* EV_CHANGESTATE: the state of tile b0, b1's event := b2 */
	case 0x13:		/* EV_NEXTSTATE (up to 9) */
	case 0x14:		/* EV_PREVSTATE */
	case 0x31: {	/* EV_CHANGESTATERANDOM: a state of [b2, b3] */
		int ev = Render_findTileEvent( render, B0 + B1 * MAP_TILES ), st;
		u32 e;
		if ( ev == -1 ) {
			break;
		}
		e = render->tileEvents[ev];
		st = EVENT_STATE( e );
		if ( op == 0x0b ) {
			CALLING( "EV_CHANGESTATE" );
			st = B2;
		} else if ( op == 0x31 ) {
			CALLING( "EV_CHANGESTATERANDOM" );
			st = B2 + App_randomBelow( app, B3 - B2 + 1 );
		} else if ( op == 0x13 ) {
			CALLING( "EV_NEXTSTATE" );
			if ( st < 9 ) {
				st++;
			}
		} else {
			CALLING( "EV_PREVSTATE" );
			if ( st != 0 ) {
				st--;
			}
		}
		render->tileEvents[ev] = ( e & 0x87ffffff ) | ( (u32)st << 27 );
		break;
	}

	case 0x0c:		/* EV_LOCK, EV_UNLOCK, EV_TOGGLELOCK of line arg */
	case 0x0d:
	case 0x0e:
		CALLING( op == 0x0c ? "EV_LOCK" : op == 0x0d ? "EV_UNLOCK" : "EV_TOGGLELOCK" );
		if ( (int)arg < 0 || (int)arg >= render->numLines ) {
			App_fatal( app, "invalid line %d", arg );
			return SCRIPT_NOT_RUN;
		}
		if ( op == 0x0c ) {
			Game_setLineLocked( game, (int)arg, 1, 0 );
		} else if ( op == 0x0d ) {
			Game_setLineLocked( game, (int)arg, 0, 0 );
		} else {
			Game_setLineLocked( game, (int)arg, !( render->lines[arg].flags & 0x400 ), 0 );
		}
		break;

	case 0x12:		/* EV_HIDE: sprite arg; bit 31: the sprites on tile b0, b1 (of tile b2, all when 0;
					 * bit 30: all but tile b2) that are not on a wall */
		CALLING( "EV_HIDE" );
		if ( !( arg & 0x80000000 ) ) {
			Sprite *s = &render->sprites[arg];
			s->info |= SPRITE_HIDDEN;
			if ( s->ent ) {
				Dbg_printf( "hiding %i", s->ent->def->name );
				s->ent->info |= ENT_DIRTY;
				Game_unlinkEntity( game, s->ent );
			}
			Canvas_updateFacing( canvas );
		} else {
			int tile = B2, invert = ( arg & 0x40000000 ) != 0;
			for ( i = 0; i < render->numSprites; i++ ) {
				Sprite	*s = &render->sprites[i];
				int		t = (int)( s->info & 0xff ) + ( ( s->info & SPRITE_WALLTEX ) ? 0x101 : 0 );
				if ( ( tile == 0 || ( invert ? tile != t : tile == t ) ) && B0 == s->x >> 6 && B1 == s->y >> 6 &&
					 !( s->info & SPRITE_ONWALL ) ) {
					s->info |= SPRITE_HIDDEN;
					if ( s->ent ) {
						s->ent->info |= ENT_DIRTY;
						Game_unlinkEntity( game, s->ent );
					}
				}
			}
		}
		break;

	case 0x15:		/* EV_INCSTAT, EV_DECSTAT: stat b0 by b1 */
	case 0x16:
		CALLING( "EV_*_INC_DEC_STAT" );
		Player_modifyStat( player, B0, op == 0x15 ? (int)B1 : -(int)B1 );
		break;

	case 0x17:		/* EV_REQSTAT: unless the player has stat b0, the event stops (with map string hi16) */
		CALLING( "EV_REQSTAT" );
		if ( !Player_hasStat( player, B0 ) ) {
			if ( arg >> 16 ) {
				Canvas_showDialog( canvas, NULL, canvas->stringGroup, (s16)( arg >> 16 ), 6, 0, 0 );
				lowerWand( player );
			}
			return SCRIPT_ABORT;
		}
		break;

	case 0x18:		/* EV_FORCEMESSAGE: map string lo16 stays on the HUD ("" clears it) */
		CALLING( "EV_FORCEMESSAGE" );
		String_clear( &canvas->text, 0 );
		Text_getString( text, canvas->stringGroup, (s16)arg, &canvas->text );
		String_clear( &hud->forced, 0 );
		if ( String_length( &canvas->text ) > 0 ) {
			Text_wrap( text, &canvas->text, 9999, &hud->forced );
		}
		break;

	case 0x19: {	/* EV_ANIM: the animation of tile (arg >> 10) & 0xff once on tile arg & 0x3ff, moved
					 * by ((arg >> 18) & 0xf) - 4 and ((arg >> 22) & 0xf) - 4 eighths of a tile */
		int dx = (int)( ( arg >> 18 ) & 0xf ) - 4, dy = (int)( ( arg >> 22 ) & 0xf ) - 4, tile = (int)( arg & 0x3ff );
		/* (a whole half tile out is pulled back by one unit) */
		int ex = dx == -4 ? 1 : dx == 4 ? -1 : 0, ey = dy == -4 ? 1 : dy == 4 ? -1 : 0;
		CALLING( "EV_ANIM" );
		Game_gspriteAllocAnim( game, ( arg >> 10 ) & 0xff, ex + TILE_CENTER( tile % 32 ) + dx * 8,
			ey + TILE_CENTER( tile / 32 ) + dy * 8, 0x20 );
		break;
	}

	case 0x1a:		/* EV_GIVEITEM: (arg >> 16) of item b0 / b1 */
		CALLING( "EV_GIVEITEM" );
		Player_give( player, B0, B1, (int)arg >> 16, 0 );
		break;

	case 0x1b:		/* EV_SAVEGAME: where the player comes back: map 6000 + b0, tile b1, b2, direction b3 */
		CALLING( "EV_SAVEGAME" );
		game->respawnMap = (u16)( B0 + 6000 );
		game->respawnX = TILE_CENTER( B1 );
		game->respawnY = TILE_CENTER( B2 );
		game->respawnDir = B3;
		break;

	case 0x1c:		/* EV_ABORTMOVE */
		CALLING( "EV_ABORTMOVE" );
		canvas->abortMove = 1;
		break;

	case 0x1d:		/* EV_SCREENSHAKE: arg & 0xfff ms, intensity b3, vibration (arg >> 12) & 0xfff */
		CALLING( "EV_SCREENSHAKE" );
		if ( !game->skipping ) {
			Canvas_startShake( canvas, (s16)( arg & 0xfff ), (s16)( arg >> 24 ), (s16)( ( arg >> 12 ) & 0xfff ) );
		}
		break;

	case 0x1e:		/* EV_CHANGEFLOORCOLOR, EV_CHANGECEILCOLOR: RGB b2, b1, b0 */
	case 0x1f: {
		u16 c = (u16)( ( ( B1 >> 3 ) << 5 ) | ( ( B0 >> 3 ) << 10 ) | ( B2 >> 3 ) );
		CALLING( op == 0x1e ? "EV_CHANGEFLOORCOLOR" : "EV_CHANGECEILCOLOR" );
		if ( op == 0x1e ) {
			render->floorColor = c;
		} else {
			render->ceilColor = c;
		}
		break;
	}

	case 0x20:		/* EV_ENABLEWEAPONS */
		CALLING( "EV_ENABLEWEAPONS" );
		if ( arg == 0 ) {
			Player_disableWeapons( player );
		} else {
			Player_enableWeapons( player );
		}
		break;

	case 0x21:		/* EV_OPENSTORE: 0 the store menu (unless it is up), else the help queued first */
		CALLING( "EV_OPENSTORE" );
		if ( arg == 0 ) {
			if ( canvas->menuSystem->menuId != 0x11 && canvas->menuSystem->menuId != 0x10 ) {
				MenuSystem_setMenu( canvas->menuSystem, 2, 0x10 );
			}
		} else if ( canvas->helpCount > 0 ) {
			Canvas_dequeueHelp( canvas, 0 );
			canvas->storeOpen = 1;
		}
		break;

	case 0x22: {	/* EV_CHANGESPRITE: the items on tile b0 & 0x1f, (arg >> 5) & 0x1f become tile arg >> 13,
					 * frame (arg >> 10) & 7 */
		int tx = (int)( arg & 0x1f ), ty = (int)( ( arg >> 5 ) & 0x1f );
		Entity *e;
		CALLING( "EV_CHANGESPRITE" );
		e = Game_getTileEntities( game, tx << 6, ty << 6 );
		if ( !e ) {
			Dbg_printf( "EV_CHANGESPRITE: Didn't find any entity at %d %d", tx, ty );
			break;
		}
		for ( ; e; e = e->next ) {
			if ( !( e->info & ENT_LINE ) && e->def->eType != ETYPE_MONSTER ) {
				Sprite *s = &render->sprites[( e->info & ENT_SPRITE_MASK ) - 1];
				s->info = ( s->info & 0xfffff000 ) | ( (int)arg >> 13 ) | ( ( ( arg >> 10 ) & 7 ) << 8 ) | SPRITE_SEEN;
				e->info |= ENT_DIRTY;
			}
		}
		break;
	}

	case 0x23:		/* EV_SPAWNPARTICLES: kind arg & 0x1f, colour (arg >> 5) & 0x1f, (arg >> 10) & 0x1f tiles in
					 * front of the view, at height (arg >> 15) & 0xff (0xff: the eyes') */
		CALLING( "EV_SPAWNPARTICLES" );
		if ( !game->skipping ) {
			int z = (int)( ( arg >> 15 ) & 0xff ), dist = (int)( ( arg >> 10 ) & 0x1f ) * 64, x, y;
			ParticleSet *set;
			if ( z == 0xff ) {
				z = render->viewZ;
			}
			x = ( render->viewX + ( ( render->sinTable[( render->viewAngle + 0x100 ) & 0x3ff] * dist ) >> 16 ) ) * 64;
			y = ( render->viewY + ( ( -render->sinTable[render->viewAngle & 0x3ff] * dist ) >> 16 ) ) * 64;
			set = Particles_spawn( app->particles, arg & 0x1f, x, y, z << 6, 1 );
			set->flags |= 6;
			set->color = particleColors[( arg >> 5 ) & 0x1f];
			Particles_start( app->particles, set, NOW_MS() );
			set->flags = 0;
		}
		break;

	case 0x24:		/* EV_REFRESHVIEW */
		CALLING( "EV_REFRESHVIEW" );
		Canvas_updateFacing( canvas );
		break;

	case 0x25:		/* EV_WAIT: arg ms (a camera's too in a nested event) */
		CALLING( "EV_WAIT" );
		self->waitUntil = (int)arg + NOW_MS();
		if ( frame->frameFlags & FRAME_NESTED ) {
			game->cameraStart += (int)arg;
			if ( canvas->state != CS_CAMERA ) {
				canvas->scriptWaitUntil = self->waitUntil;
			}
		}
		return SCRIPT_PAUSED;

	case 0x26:		/* EV_REQITEM: unless the player has between min and max of item b0 / b1 (b2: odd, at least
					 * b2 >> 1; even, at most b2 >> 1) the event stops with map string b3; 0x76 a dialog */
	case 0x76: {
		int min, max;
		CALLING( "EV_REQITEM" );
		if ( B2 & 1 ) {
			min = B2 >> 1;
			max = 9999999;
		} else {
			min = 0;
			max = B2 >> 1;
		}
		if ( !Player_hasItemCount( player, B0, B1, min, max ) ) {
			if ( op == 0x76 ) {
				Canvas_showDialog( canvas, NULL, canvas->stringGroup, B3, 6, 1, 0 );
			} else {
				Hud_showString( hud, canvas->stringGroup, B3, 1 );
			}
			return SCRIPT_ABORT;
		}
		break;
	}

	case 0x28:		/* EV_NOTE: note lo16 for the journal */
		CALLING( "EV_NOTE" );
		Player_addNote( player, (s16)arg, 1 );
		Player_showHelp( player, 0xc, 0 );
		break;

	case 0x29:		/* EV_ENDGAME */
		CALLING( "EV_ENDGAME" );
		player->gameEnded = 1;
		canvas->endGame = 1;
		game->skipping = 0;
		game->skipUntil = 0;
		game->skippable = 0;
		Canvas_startFade( canvas, 0, 0x10 );
		Canvas_setState( canvas, CS_LOADING );
		app->menuSystem->unk184d4 = 0xffff;
		MenuSystem_setMenu( app->menuSystem, 2, 0x03e80034 );
		return SCRIPT_ABORT;

	case 0x2a:		/* EV_PLAYSOUND lo16 */
		CALLING( "EV_PLAYSOUND" );
		if ( !game->skipping ) {
			Sound_play( sound, NULL, (int)( arg & 0xffff ), 0, 3 );
		}
		break;

	case 0x2c:		/* EV_WANDCHAT: the wand says map string lo16 */
		CALLING( "EV_WANDCHAT" );
		if ( !game->skipping ) {
			Hud_wandChat( hud, canvas->stringGroup, (s16)arg );
		}
		break;

	case 0x2d: {	/* EV_WAKEMONSTER: the monster of sprite arg turns on the player */
		Sprite *s = &render->sprites[arg];
		Entity *e = s->ent;
		CALLING( "EV_WAKEMONSTER" );
		if ( !e ) {
			App_fatal( app, "EV_WAKEMONSTER on non-entity at %d", arg );
			return SCRIPT_NOT_RUN;
		}
		if ( s->info & SPRITE_HIDDEN ) {
			App_fatal( app, "EV_WAKEMONSTER on invisible entity at index %d (x:%d y:%d)", arg, s->x >> 6, s->y >> 6 );
			return SCRIPT_NOT_RUN;
		}
		if ( e->def->eType == ETYPE_MONSTER && !( e->info & 0x400a0000 ) ) {
			e->info |= ENT_AGGRO;
			Game_activateEx( game, s->ent, 1, 0 );
		}
		break;
	}

	case 0x2e:		/* EV_LERPFLAT: the floor (b0 0) or ceiling flat becomes b1, over (arg >> 16) ms */
		CALLING( "EV_LERPFLAT" );
		if ( ( arg >> 16 ) == 0 ) {
			if ( B0 == 0 ) {
				render->floorFlat = (u8)B1;
			} else {
				render->ceilFlat = (u8)B1;
			}
		} else {
			FlatLerp *l = &render->flatLerps[B0];
			l->duration = (int)( arg >> 16 );
			l->startTime = app->time;
			l->to = B1;
			l->from = B0 == 0 ? render->curFloorFlat : render->curCeilFlat;
		}
		break;

	case 0x30:		/* EV_LERPSPRITE: sprite (arg >> 7) & 0x3ff to tile (arg >> 17) & 0x1f, (arg >> 22) & 0x1f,
					 * height ((arg >> 27) & 0x1f) * 8 - 32, in (arg & 0x7f) * 100 ms; the thread waits */
	case 0x4b:		/* ... without waiting */
	case 0x5f:		/* ... to sprite (arg >> 17) & 0x3ff */
	case 0x60:		/* ... keeping its place in the tile */
	case 0x77: {	/* ... the DS's own (LERP_77) */
		int		spr = (int)( ( arg >> 7 ) & 0x3ff ), dtx, dty, dz, z;
		Sprite	*s;
		LerpSprite *ls;
		CALLING( "EV_LERPSPRITE" );
		if ( op == 0x5f ) {
			Sprite *t = &render->sprites[( (s16)( arg >> 16 ) >> 1 ) & 0x3ff];
			dz = t->z;
			dtx = t->x >> 6;
			dty = t->y >> 6;
		} else {
			dtx = (int)( ( arg >> 17 ) & 0x1f );
			dty = (int)( ( arg >> 22 ) & 0x1f );
			dz = (int)( ( arg >> 27 ) & 0x1f );
		}
		z = dz * 8 - 0x20;
		s = &render->sprites[spr];
		ls = Game_allocLerpSprite( game, self, spr );
		ls->param = s->param;		/* (before the check: the allocation stops the game when it fails) */
		if ( s->ent && ( s->ent->def->tile == 0x7b || s->ent->def->tile == 4 ) ) {
			/* a falling block: one already down shakes the screen */
			if ( s->z == z ) {
				Sound_play( sound, s->ent, 0xba, 0, 3 );
				Canvas_startShake( canvas, 500, 3, 200 );
				s->info &= 0xf7fff0ff;
			} else {
				s->info |= SPRITE_SEEN;
				if ( z == 0 ) {
					z = 0x20;
				}
				s->ent->info |= 0x80080000;
			}
		}
		if ( !ls ) {
			return SCRIPT_NOT_RUN;
		}
		if ( op != 0x60 ) {
			ls->dstX = (s16)TILE_CENTER( dtx );
			ls->dstY = (s16)TILE_CENTER( dty );
		} else {
			ls->dstX = (s16)( s->x + ( dtx - ( s->x >> 6 ) ) * 64 );
			ls->dstY = (s16)( s->y + ( dty - ( s->y >> 6 ) ) * 64 );
		}
		if ( s->ent ) {
			s->ent->info = ( s->ent->info & ~ENT_LERPING ) | 0x88000000;
			if ( s->ent->monster ) {
				s->ent->monster->destX = ls->dstX;
				s->ent->monster->destY = ls->dstY;
			}
		}
		ls->dstZ = (s16)z;
		ls->srcX = s->x;
		ls->srcY = s->y;
		ls->srcZ = s->z;
		ls->dstScale = ls->srcScale = s->scale;
		ls->startTime = app->gameTime;
		ls->duration = (int)( arg & 0x7f ) * 100;
		{
			int dx = ls->dstX - ls->srcX, dy = ls->dstY - ls->srcY;
			ls->dist = (s16)FixedSqrt( (u64)( ( dx * dx + dy * dy ) * 0x100 ) );
		}
		ls->flags = op == 0x4b ? LERP_NO_WAIT : 0;
		if ( op == 0x77 ) {
			ls->flags |= LERP_77;
		}
		if ( !( ls->flags & LERP_NO_WAIT ) ) {
			game->yieldFlag = 1;
			return SCRIPT_PAUSED;
		}
		break;
	}

	case 0x32:		/* EV_SWITCHON, EV_SWITCHOFF, EV_TOGGLESWITCH: the switches on tile b0, b1 (the y is
					 * arg >> 8 whole: b2 is 0 in every map) */
	case 0x33:
	case 0x34: {
		Entity *e = Game_getTileEntities( game, B0 << 6, (int)( arg >> 8 ) << 6 );
		CALLING( op == 0x32 ? "EV_SWITCHON" : op == 0x33 ? "EV_SWITCHOFF" : "EV_TOGGLESWITCH" );
		for ( ; e; e = e->next ) {
			if ( e->def->eType != ETYPE_SWITCH ) {
				continue;
			}
			if ( e->def->eSubType == 2 && op != 0x33 ) {
				Game_setSwitch( game, e, 1 );
			} else if ( e->def->eSubType == 1 && op != 0x32 ) {
				Game_setSwitch( game, e, 0 );
			}
		}
		if ( op != 0x34 ) {
			Sound_play( sound, NULL, 0xe4, 0, 3 );
		}
		break;
	}

	case 0x35:		/* EV_CAMERATIME: the keys' duration (Game_loadCameras reads it) */
		CALLING( "EV_CAMERATIME" );
		break;

	case 0x36: {	/* EV_CAMERAKEY: camera b0 from its key b1 - 1 (Game_loadCameras rewrote the arg);
					 * b1 0 does nothing */
		int		key = (s8)B1;
		Camera	*cam;
		CameraKey *k;
		CALLING( "EV_CAMERAKEY" );
		if ( key <= 0 ) {
			break;
		}
		cam = &game->cameras[B0];
		game->cameraKey = (s8)( key - 1 );
		game->activeCamera = cam;
		cam->keyDone = 0;
		cam->pitch = cam->keys[game->cameraKey].pitch;
		cam->roll = cam->keys[game->cameraKey].roll;
		cam->thread = self;
		game->cameraStart = NOW_MS();
		if ( key == 1 ) {
			/* keys marked so start where the player is */
			for ( i = 0; i < cam->numKeys; i++ ) {
				k = &cam->keys[i];
				if ( k->fromPlayer & 1 ) {
					k->x = (s16)canvas->viewX;
				}
				if ( k->fromPlayer & 2 ) {
					k->y = (s16)canvas->viewY;
				}
				if ( k->fromPlayer & 4 ) {
					k->z = (s16)canvas->viewZ;
				}
				if ( k->fromPlayer & 8 ) {
					k->yaw = (s16)( canvas->viewAngle & 0x3ff );
				}
			}
		}
		k = &cam->keys[game->cameraKey];
		cam->x = k->x << 12;
		cam->y = k->y << 12;
		cam->z = k->z << 12;
		cam->yaw = k->yaw;
		if ( canvas->state != CS_CAMERA ) {
			Canvas_setState( canvas, CS_CAMERA );
		}
		game->yieldFlag = 1;
		return SCRIPT_PAUSED;
	}

	case 0x37:		/* a camera key's place (with 0x38, see Game_loadCameras) */
		break;

	case 0x3a:		/* EV_LERPSPRITEPARAM: the flags of the move of sprite (arg >> 16) & 0x3ff := b0 */
		CALLING( "EV_LERPSPRITEPARAM" );
		for ( i = 0; i < MAX_LERP_SPRITES; i++ ) {
			if ( game->lerpSprites[i].sprite - 1 == (int)( ( arg >> 16 ) & 0x3ff ) ) {
				game->lerpSprites[i].flags = (u8)arg;
				return SCRIPT_DONE;
			}
		}
		break;

	case 0x3c:		/* EV_ACTIVATEFIREPIT b0: on with bit 8 */
		CALLING( "EV_ACTIVATEFIREPIT" );
		if ( arg & 0x100 ) {
			player->firePits |= 1u << B0;
			Game_setFirePit( game, B0, 1 );
		} else {
			player->firePits &= ~( 1u << B0 );
			Game_setFirePit( game, B0, 0 );
		}
		break;

	case 0x3d: {	/* EV_SHOWCHATBUBBLE: the NPC of sprite lo16 has something to say (b2) */
		Sprite *s = &render->sprites[arg & 0xffff];
		CALLING( "EV_SHOWCHATBUBBLE" );
		if ( !s->ent || !Entity_isNPC( s->ent ) ) {
			App_setErrorStr( app, "EV_SHOWCHATBUBBLE: Sprite at index %d was not an npc", arg & 0xffff );
			APP_ERROR( EDEBUG, "EDEBUG", "ScriptThread.cpp", 1446, "executeEvent" );
		} else {
			s->ent->param = B2;
			s->ent->info |= ENT_DIRTY;
		}
		break;
	}

	case 0x3e:		/* EV_STARTCINEMATIC: skippable from 500 ms on (arg 0) or not at all */
		CALLING( "EV_STARTCINEMATIC" );
		game->skipping = 0;
		game->skipUntil = arg == 0 ? NOW_MS() + 500 : 0x7fffffff;
		game->skippable = 1;
		break;

	case 0x3f:		/* EV_ENDCINEMATIC */
		CALLING( "EV_ENDCINEMATIC" );
		game->skipping = 0;
		game->skipUntil = 0;
		game->skippable = 0;
		canvas->unk9ac = 0;
		canvas->unk9d4 = 0;
		Canvas_setState( canvas, CS_PLAYING );
		break;

	case 0x40:		/* EV_GLOBALFLOOR, EV_GLOBALCEIL: one flat for the whole map; EV_OSCILLATEFLOOR: water */
		CALLING( "EV_GLOBALFLOOR" );
		render->globalFloor = arg == 1;
		break;
	case 0x41:
		CALLING( "EV_GLOBALCEIL" );
		render->globalCeil = arg == 1;
		break;
	case 0x42:
		CALLING( "EV_OSCILLATEFLOOR" );
		render->oscillate = arg == 1;
		break;

	case 0x43:		/* EV_NAMEENTITY: map string lo16 names the entity of sprite (arg >> 16), or (bit 31)
					 * the entity on tile (arg >> 16) & 0x1f, (arg >> 21) & 0x1f */
		CALLING( "EV_NAMEENTITY" );
		if ( !( arg & 0x80000000 ) ) {
			Entity *e = render->sprites[( arg >> 16 ) & 0xffff].ent;
			if ( !e ) {
				App_setErrorStr( app, "EV_NAMEENTITY: sprite at index %d is not an Entity", ( arg >> 16 ) & 0xffff );
				APP_ERROR( EDEBUG, "EDEBUG", "ScriptThread.cpp", 1509, "executeEvent" );
			} else {
				e->name = (u32)canvas->stringGroup << 16 | ( arg & 0xffff );
			}
		} else {
			Entity *e = Game_findEntityAt( game, (int)( ( arg >> 16 ) & 0x1f ) << 6, (int)( ( arg >> 21 ) & 0x1f ) << 6, -1 );
			if ( e ) {
				e->name = (u32)canvas->stringGroup << 16 | (u32)(s16)arg;
			}
		}
		break;

	case 0x44: {	/* EV_MONSTERSTAT: stat (arg >> 17) & 0xf of the monster of sprite (arg >> 21) & 0x3ff :=
					 * lo16 (0 health, 2 defense, 3 strength, 4 accuracy) */
		int		spr = (int)( ( arg >> 21 ) & 0x3ff ), v = (int)( arg & 0xffff );
		Entity	*e = render->sprites[spr].ent;
		Monster	*m = e ? e->monster : NULL;
		CALLING( "EV_MONSTERSTAT" );
		if ( !m ) {
			App_setErrorStr( app, "Couldn't find monster for sprite %d", spr );
			APP_ERROR( EDEBUG, "EDEBUG", "ScriptThread.cpp", 1564, "executeEvent" );
			break;
		}
		switch ( ( arg >> 17 ) & 0xf ) {
		case 0:
			CombatEntity_setMaxHealth( &m->ce, v );
			CombatEntity_setHealth( &e->monster->ce, v );
			break;
		case 2:
			CombatEntity_setDefense( &m->ce, v );
			break;
		case 3:
			CombatEntity_setStrength( &m->ce, v );
			break;
		case 4:
			CombatEntity_setAccuracy( &m->ce, v );
			break;
		default:
			App_setErrorStr( app, "Unknown monster stat %d for sprite %d", ( arg >> 17 ) & 0xf, spr );
			APP_ERROR( EDEBUG, "EDEBUG", "ScriptThread.cpp", 1556, "executeEvent" );
			break;
		}
		e->info |= ENT_DIRTY;
		break;
	}

	case 0x45: {	/* EV_MONSTERFLAGS: the flags of the monster of sprite arg & 0x3ff: bits 10..25 set
					 * (arg >> 26 == 1), cleared (2) or written (else) */
		Entity	*e = render->sprites[arg & 0x3ff].ent;
		Monster	*m = e ? e->monster : NULL;
		u16		bits = (u16)( ( arg << 6 ) >> 16 );
		CALLING( "EV_MONSTERFLAGS" );
		if ( !m ) {
			App_setErrorStr( app, "EV_MONSTERFLAGS: Sprite at index %d was not an entity", arg & 0x3ff );
			APP_ERROR( EDEBUG, "EDEBUG", "ScriptThread.cpp", 1590, "executeEvent" );
			break;
		}
		if ( (int)arg >> 26 == 1 ) {
			m->flags |= bits;
		} else if ( (int)arg >> 26 == 2 ) {
			m->flags &= (u16)~bits;
		} else {
			m->flags = bits;
		}
		e->info |= ENT_DIRTY;
		break;
	}

	case 0x46: {	/* EV_CLEARMONSTEREFFECTS of sprite arg: not burning or frozen, out of the fight */
		Entity *e = render->sprites[arg].ent;
		CALLING( "EV_CLEARMONSTEREFFECTS" );
		if ( e && e->monster ) {
			Monster *m = e->monster;
			m->burning = 0;
			m->flags &= ~0x2000;
			m->frozen = 0;
			m->flags &= ~0x200;
			if ( m->goal.type == 4 ) {
				MonsterGoal_reset( &m->goal );
			}
			Game_removeFromCombat( e );
		}
		break;
	}

	case 0x47:		/* EV_DEACTIVATE the monster of sprite arg & 0x3ff */
		CALLING( "EV_DEACTIVATE" );
		if ( !render->sprites[arg & 0x3ff].ent ) {
			App_setErrorStr( app, "EV_DEACTIVATE: Sprite at index %d was not an entity", arg & 0x3ff );
			APP_ERROR( EDEBUG, "EDEBUG", "ScriptThread.cpp", 1642, "executeEvent" );
		} else {
			Game_deactivate( game, render->sprites[arg & 0x3ff].ent );
			Canvas_updateFacing( canvas );
		}
		break;

	case 0x48:		/* EV_UPDATEWEAPON: weapon b0 taken away (b1 0) or given and put in hand */
		CALLING( "EV_UPDATEWEAPON" );
		if ( B1 == 0 ) {
			player->weapons &= ~( 1u << B0 );
			if ( player->ce.weapon == B0 ) {
				Player_selectNextWeapon( player );
			}
			if ( B0 == 0 ) {
				Player_showHelp( player, 0x10, 1 );
			}
		} else {
			Player_give( player, 1, B0, 1, 0 );
			Player_selectWeapon( player, B0 );
		}
		if ( B0 == 0 ) {
			WeaponView_reset( app->weaponView );
		}
		break;

	case 0x49:		/* EV_LERPBLOCK: the block on tile (arg >> 15) & 0x1f, (arg >> 10) & 0x1f slides to tile
					 * (arg >> 5) & 0x1f, arg & 0x1f in (arg >> 20) * 100 ms; 0x61 blocks the way meanwhile */
	case 0x61: {
		int x0 = TILE_CENTER( ( arg >> 15 ) & 0x1f ), y0 = TILE_CENTER( ( arg >> 10 ) & 0x1f );
		CALLING( "EV_LERPBLOCK" );
		Game_addMovingBlock( game, x0, y0, TILE_CENTER( ( arg >> 5 ) & 0x1f ), TILE_CENTER( arg & 0x1f ),
			(int)( arg >> 20 ) * 100, op == 0x61 );
		if ( Render_tileTouchesWall( render, x0 >> 6, y0 >> 6, 0 ) ) {
			Sound_playAt( sound, (s16)x0, (s16)y0, 0xba, 0, 3, 0, 0, 0 );
		}
		break;
	}

	case 0x4a:		/* EV_TAKEITEM: (arg >> 16) of item b0 / b1 */
		CALLING( "EV_TAKEITEM" );
		Player_give( player, B0, B1, -( (int)arg >> 16 ), 0 );
		break;

	case 0x4e:		/* EV_QUELLWAND: the wand stops wanting to talk */
		CALLING( "EV_QUELLWAND" );
		Player_setWandMood( player, 0 );
		hud->wandChat = 0;
		break;

	case 0x4f: {	/* EV_AIMOVETO: the monster of sprite lo16 walks to tile b2, b3 */
		Entity *e = render->sprites[arg & 0xffff].ent;
		CALLING( "EV_AIMOVETO" );
		if ( !e ) {
			App_fatal( app, "EV_AIMOVETO: Sprite at index %d was not an entity", arg & 0xffff );
		} else {
			Monster *m = e->monster;
			MonsterGoal_reset( &m->goal );
			m->goal.type = 1;
			m->goal.x = (u8)B2;
			m->goal.y = (u8)B3;
		}
		break;
	}

	case 0x50: {	/* EV_SHOWCORPSE: the monster of sprite lo16 lies there dead */
		Sprite *s = &render->sprites[arg & 0xffff];
		Entity *e = s->ent;
		CALLING( "EV_SHOWCORPSE" );
		e->info |= ENT_CORPSE | ENT_DIRTY;
		e->def = EntityDefs_find( app->entityDefs, ETYPE_CORPSE, e->def->eSubType, e->def->parm );
		e->monster->flags |= 0x80;
		s->info = ( s->info & ~( SPRITE_FRAME | SPRITE_HIDDEN ) ) | 0x800;
		if ( e->info & ENT_IN_RING ) {
			Game_deactivate( game, e );
		}
		Game_linkEntity( game, e, s->x >> 6, s->y >> 6 );
		/* on the hardest setting it gets up again */
		if ( game->difficulty == 2 && e->def->eSubType < 0x10 ) {
			e->monster->goal.type = 0xf;
			e->monster->goal.turns = 3;
		}
		break;
	}

	case 0x51: {	/* EV_GIVERELIQUARYLOOT: the reliquary on tile b0, b1 opens */
		Entity *e;
		CALLING( "EV_GIVERELIQUARYLOOT" );
		for ( e = Game_getTileEntities( game, B0 << 6, (int)( arg >> 8 ) << 6 ); e; e = e->next ) {
			if ( e->def->eType == ETYPE_DECOR && e->def->eSubType == 3 ) {
				Sprite *s = &render->sprites[( e->info & ENT_SPRITE_MASK ) - 1];
				s->info = ( s->info & 0xffffff00 ) | 0x9b;
				e->info |= ENT_DIRTY;
				Game_unlinkEntity( game, e );
				String_clear( &canvas->text, 0 );
				Text_getString( text, 0, 0xcd, &canvas->text );
				Entity_openReliquary( e, e->tile % 32, e->tile / 32, 4, &canvas->text );
				Sound_play( sound, NULL, 0xa4, 0, 3 );
				return SCRIPT_DONE;
			}
		}
		break;
	}

	case 0x52: {	/* EV_LERPSPRITESCALE: sprite (arg >> 16) to scale b1 in b0 * 100 ms (b0 0: at once) */
		int spr = (s16)( arg >> 16 );
		Sprite *s = &render->sprites[spr];
		CALLING( "EV_LERPSPRITESCALE" );
		if ( B0 ) {
			LerpSprite *ls = Game_allocLerpSprite( game, self, spr );
			if ( !ls ) {
				return SCRIPT_NOT_RUN;
			}
			ls->dstX = ls->srcX = s->x;
			ls->dstY = ls->srcY = s->y;
			ls->dstZ = ls->srcZ = s->z;
			ls->param = s->param;
			ls->srcScale = s->scale;
			ls->dstScale = (u8)B1;
			ls->startTime = app->gameTime;
			ls->duration = (int)B0 * 100;
			ls->flags = 0;
			game->yieldFlag = 1;
			if ( s->ent && s->ent->monster ) {
				s->ent->monster->flags |= 0x400;
			}
			return SCRIPT_PAUSED;
		}
		s->scale = (u8)B1;
		break;
	}

	case 0x53: {	/* EV_CRYSTALHEAL: a crystal heals 20 (when the player has no charge to take or is hurt) */
		u8 before = player->crystalCharges;
		CALLING( "EV_CRYSTALHEAL" );
		Player_give( player, 3, 1, 5, 0 );
		if ( before == player->crystalCharges &&
			 CombatEntity_getHealth( &player->ce ) == CombatEntity_getMaxHealth( &player->ce ) ) {
			Hud_gameMessage( hud, 0xcf, 0 );
			game->yieldFlag = 1;
			return SCRIPT_DONE;
		}
		Player_addHealth( player, 20 );
		if ( !Sound_isPlaying( sound, player->crystalSound ) ) {
			player->crystalSound = Sound_play( sound, NULL, 0x77, 0, 3 );
		}
		break;
	}

	case 0x54: {	/* EV_AWARDSECRET: 5 XP, or for a map's last secret 1/16 of a level */
		int found, total;
		CALLING( "EV_AWARDSECRET" );
		Hud_gameMessage( hud, 0xcc, 0 );
		Sound_play( sound, NULL, 0xe4, 0, 3 );
		Sound_play( sound, NULL, 0xc5, 0, 3 );
		Player_countSecrets( player, &found, &total );
		if ( found + 1 == total && !( player->secretsMaps & ( 1u << ( ( canvas->mapId - 6000 ) & 0xff ) ) ) ) {
			String *msg;
			int bonus;
			Sound_play( sound, NULL, 0x8c, 2, 5 );
			bonus = ( Player_xpForLevel( player, player->level ) - Player_xpForLevel( player, player->level - 1 ) ) >> 4;
			msg = &canvas->messages[canvas->messageIndex];
			canvas->messageIndex = ( canvas->messageIndex + 1 ) % 2;
			String_clear( msg, 0 );
			text->numArgs = 0;
			Text_setArgString( text, &render->mapName );
			Text_setArgInt( text, bonus );
			Text_getString( text, 0, 0x16, msg );
			Canvas_addHelpString( canvas, msg, 2 );
			Player_addXP( player, bonus );
			player->secretsMaps |= 1u << ( ( canvas->mapId - 6000 ) & 0xff );
			total = bonus;		/* (the debug text below then shows it) */
		} else {
			Player_addXP( player, 5 );
		}
		Hud_randomBark( hud, 8, 0 );
		Dbg_printf( "found secret %d/%d", found, total );
		break;
	}

	case 0x55: {	/* EV_STEALGOLD: lo16 gold is taken; with bit 31 clear, map string hi16 says how much */
		int before = player->gold, stolen;
		CALLING( "EV_STEALGOLD" );
		Player_give( player, 4, 0, -(int)( arg & 0xffff ), 0 );
		stolen = before - player->gold;
		app->statGoldB -= stolen;
		app->statGoldA -= stolen;
		if ( stolen > 0 ) {
			game->goldStolen += (s16)stolen;
			if ( (int)arg >= 0 ) {
				String *buf = Hud_messageBuffer( hud, 3 );
				String_clear( buf, 0 );
				text->numArgs = 0;
				Text_setArgInt( text, stolen );
				Text_getString( text, canvas->stringGroup, (s16)( arg >> 16 ), buf );
				Hud_finishMessage( hud );
			}
			Sound_play( sound, NULL, 0x93, 0, 3 );
			Canvas_startShake( canvas, 0, 2, 400 );
		}
		break;
	}

	case 0x56: {	/* EV_GAYAHEADFRAME: the frame of Gaya's head on tile b0, b1 := b2 */
		Entity *e;
		CALLING( "EV_GAYAHEADFRAME" );
		e = Game_findEntityAt( game, B0 << 6, B1 << 6, 0x80 );
		if ( !e ) {
			App_fatal( app, "EV_GAYAHEADFRAME: NULL ent at %d %d", B0, B1 );
		} else {
			e->param = B2;
		}
		break;
	}

	case 0x57:		/* EV_DAMAGEENTITY: b0 damage (and b1 armour) to the player (hi16 0xffff), else lo16
					 * damage to the entity of sprite hi16 */
		CALLING( "EV_DAMAGEENTITY" );
		if ( ( ( arg >> 16 ) & 0xffff ) == 0xffff ) {
			Player_hurtFeedback( player, 0 );
			Player_takeDamage( player, B0, 0 );
			CombatEntity_addArmor( &player->ce, -(int)B1 );
		} else {
			Entity *e = render->sprites[( arg >> 16 ) & 0xffff].ent;
			if ( !e ) {
				App_setErrorStr( app, "EV_DAMAGEENTITY: Sprite at index %d was not an entity", ( arg >> 16 ) & 0xffff );
				APP_ERROR( EDEBUG, "EDEBUG", "ScriptThread.cpp", 1669, "executeEvent" );
			} else if ( !e->monster ) {
				Entity_kill( e, 1 );
			} else {
				Entity_takeDamage( e, (int)( arg & 0xffff ) );
				if ( CombatEntity_getHealth( &e->monster->ce ) < 1 ) {
					Entity_kill( e, 1 );
				}
			}
		}
		break;

	case 0x58:		/* EV_SETDRAGONMOOD := arg (0..255) */
		CALLING( "EV_SETDRAGONMOOD" );
		if ( (int)arg >= 0 && (int)arg < 0x100 ) {
			player->dragonMood = (u8)arg;
		}
		break;

	case 0x59:		/* EV_ADJUSTDRAGONMOOD by arg */
		CALLING( "EV_ADJUSTDRAGONMOOD" );
		Player_adjustDragonMood( player, (int)arg );
		break;

	case 0x5a: {	/* EV_AIGOAL: the monster of sprite lo16 gets goal b2 (4: for 20 turns); a fight it
					 * starts makes the thread wait */
		Sprite *s = &render->sprites[arg & 0xffff];
		Monster *m;
		CALLING( "EV_AIGOAL" );
		if ( !s->ent ) {
			App_fatal( app, "EV_AIGOAL: Sprite at index %d was not an entity", arg & 0xffff );
			break;
		}
		game->yieldFlag = 1;
		m = s->ent->monster;
		MonsterGoal_reset( &m->goal );
		m->goal.type = (u8)B2;
		if ( B2 == 4 ) {
			m->goal.turns = 20;
		}
		Game_removeFromCombat( s->ent );
		if ( m->goal.type == 3 || m->goal.type == 10 ) {
			Entity_aiThink( s->ent );
		}
		m->goal.flags &= 0xb7;
		if ( game->combatMonsters ) {
			frame->frameFlags |= FRAME_COMBAT;
			Combat_start( app->combat, game->combatMonsters, game->combatMonsters->monster->target, 0 );
			return SCRIPT_PAUSED;
		}
		break;
	}

	case 0x5b:		/* EV_LEVELSCRIPT: the boss fight's reinforcements */
		CALLING( "EV_LEVELSCRIPT" );
		Game_updateBossReinforcements( game, B0, (int)( ( arg & 0xffffff ) >> 8 ) );
		break;

	case 0x5c: {	/* EV_FADEOUT for lo16 ms (bit 31 ..., bit 30 ...) */
		int mode = ( arg & 0x80000000 ) ? 5 : 4;
		CALLING( "EV_FADEOUT" );
		if ( arg & 0x40000000 ) {
			mode |= 8;
		}
		Canvas_startFade( canvas, (int)( arg & 0xffff ), mode );
		break;
	}

	case 0x5d:		/* EV_KNOCKBACK: the player is pushed b2 tiles away from tile b0, b1 */
		CALLING( "EV_KNOCKBACK" );
		Entity_knockback( &game->entities[1], TILE_CENTER( B0 ), TILE_CENTER( B1 ), B2 );
		break;

	case 0x5e:		/* EV_REQMOOD: unless the dragon's mood is in [b2, b3], map string lo16 and the event stops */
		CALLING( "EV_REQMOOD" );
		if ( B3 < player->dragonMood || player->dragonMood < B2 ) {
			Hud_showString( hud, canvas->stringGroup, (s16)arg, 1 );
			return SCRIPT_ABORT;
		}
		break;

	case 0x62:		/* EV_SHOWHAMMERCUES (bit 0) */
		CALLING( "EV_SHOWHAMMERCUES" );
		player->hammerCuesTime = ( arg & 1 ) ? app->gameTime : 0;
		break;

	case 0x63: {	/* EV_ENTITYFRAME: sprite lo16 shows frame b2 (0xff: its own again; b3 0 keeps it) */
		Sprite *s = &render->sprites[arg & 0xffff];
		CALLING( "EV_ENTITYFRAME" );
		if ( B2 == 0xff ) {
			s->info &= 0xf7fff0ff;
		} else {
			s->info = ( s->info & ~SPRITE_FRAME ) | ( B2 << 8 );
			if ( B3 == 0 ) {
				s->info |= SPRITE_SEEN;
			}
		}
		if ( s->ent ) {
			u32 t = s->info & 0xff;
			/* (a fire or a fountain turned off: its sound too) */
			if ( ( t == 0x80 || t == 0xc3 ) && B2 == 1 ) {
				Sound_setEmitter( sound, s->ent->emitter, 0 );
			}
			s->ent->info |= ENT_DIRTY;
		}
		break;
	}

	case 0x64:		/* EV_RESETCMDINDEX */
		CALLING( "EV_RESETCMDINDEX" );
		return SCRIPT_RESTART;

	case 0x65:		/* EV_SPAWNENTITYPARTICLES: kind (arg >> 10) & 0x1f, colour (arg >> 15) & 0x1f at sprite
					 * arg & 0x3ff */
		CALLING( "EV_SPAWNENTITYPARTICLES" );
		if ( !game->skipping ) {
			Sprite *s = &render->sprites[arg & 0x3ff];
			ParticleSet *set;
			set = Particles_spawn( app->particles, ( arg >> 10 ) & 0x1f, s->x << 6, s->y << 6, s->z << 6, 1 );
			set->flags |= 6;
			set->color = particleColors[( arg >> 15 ) & 0x1f];
			Particles_start( app->particles, set, NOW_MS() );
			set->flags = 0;
		}
		break;

	case 0x66:		/* EV_ENDCOMBAT */
		CALLING( "EV_ENDCOMBAT" );
		while ( game->combatMonsters ) {
			Game_removeFromCombat( game->combatMonsters );
		}
		if ( canvas->state == CS_COMBAT ) {
			Canvas_setState( canvas, CS_PLAYING );
		}
		break;

	case 0x69:		/* EV_MARKTILE, EV_UNMARKTILE: tile lo16 at location hi16: 0 map flag 0x80, 1 0x10
					 * (seen), 2 0x100, 3 a "monster clip" entity that keeps monsters off it */
	case 0x6e: {
		int tile = (int)( arg & 0xffff ), mark = op == 0x69;
		CALLING( mark ? "EV_MARKTILE" : "EV_UNMARKTILE" );
		switch ( arg >> 16 ) {
		case 0:
			render->mapFlags[tile] = mark ? render->mapFlags[tile] | 0x80 : render->mapFlags[tile] & 0xff7f;
			break;
		case 1:
			render->mapFlags[tile] = mark ? render->mapFlags[tile] | 0x10 : render->mapFlags[tile] & 0xffef;
			break;
		case 2:
			render->mapFlags[tile] = mark ? render->mapFlags[tile] | 0x100 : render->mapFlags[tile] & 0xfeff;
			break;
		case 3: {
			Entity *clip = NULL, *e;
			for ( i = 0; i < 16; i++ ) {
				e = &game->entities[i + 2];
				if ( !( e->info & ENT_LINKED ) ) {
					clip = mark ? e : clip;		/* (the last free one) */
				} else if ( e->tile == tile ) {
					if ( mark ) {
						Dbg_printf( "Warning: EV_MARKTILE called for tile that already had MONSTERCLIP %d %d",
							tile & 0x1f, tile >> 5 );
						return SCRIPT_DONE;
					}
					clip = e;
					break;
				}
			}
			if ( mark ) {
				if ( !clip ) {
					App_setErrorStr( app, "MAX_MONSTERCLIP_ENTITIES from EV_MARKTILE" );
					APP_ERROR( EFAILED, "EFAILED", "ScriptThread.cpp", 1964, "executeEvent" );
					return SCRIPT_NOT_RUN;
				}
				Game_linkEntity( game, clip, tile & 0x1f, tile >> 5 );
			} else if ( !clip ) {
				Dbg_printf( "Warning: EV_UNMARKTILE called for tile without MONSTERCLIP %d %d", tile & 0x1f, tile >> 5 );
			} else {
				Game_unlinkEntity( game, clip );
			}
			break;
		}
		default:
			App_setErrorStr( app, mark ? "Invalid location %d for EV_MARKTILE" : "Invalid location %d for EV_UNMARKTILE",
				arg >> 16 );
			APP_ERROR( EFAILED, "EFAILED", "ScriptThread.cpp", mark ? 1972 : 2006, "executeEvent" );
			return SCRIPT_NOT_RUN;
		}
		break;
	}

	case 0x6a:		/* EV_LAUNCHFLAMES from tile b0, b1 to tile b2, b3 */
		CALLING( "EV_LAUNCHFLAMES" );
		Combat_launchFlames( app->combat, TILE_CENTER( B0 ), TILE_CENTER( B1 ), TILE_CENTER( B2 ), TILE_CENTER( B3 ) );
		break;

	case 0x6b:		/* EV_TOUCHENTITIES: what lies on the player's tile is touched */
		CALLING( "EV_TOUCHENTITIES" );
		Game_touchTile( game, canvas->destX, canvas->destY, 1 );
		break;

	case 0x6c: {	/* EV_TURNPLAYERTO direction arg, the short way round */
		int to, v;
		CALLING( "EV_TURNPLAYERTO" );
		canvas->destAngle = Util_DirToAngle( (int)arg );
		canvas->viewAngle &= 0x3ff;
		to = canvas->destAngle;
		v = canvas->viewAngle;
		if ( abs( v - ( to + 0x400 ) ) < abs( v - to ) ) {
			canvas->destAngle += 0x400;
		} else if ( abs( v - ( to - 0x400 ) ) < abs( v - to ) ) {
			canvas->destAngle -= 0x400;
		}
		canvas->turning = 2;
		break;
	}

	case 0x6d: {	/* EV_RESPAWNMONSTER: the dead monster of sprite arg & 0x3ff comes back on tile
					 * (arg >> 10) & 0x3ff; bit 20: angry and active; bit 21: the event stops if it cannot */
		int		tile = (int)( ( arg >> 10 ) & 0x3ff ), x = ( tile % 32 ) * 64, y = ( tile / 32 ) * 64;
		u32		opts = arg >> 20;
		Entity	*e = render->sprites[arg & 0x3ff].ent, *there;
		CALLING( "EV_RESPAWNMONSTER" );
		if ( !e ) {
			App_fatal( app, "EV_RESPAWNMONSTER on non-entity at %d", arg & 0x3ff );
			return SCRIPT_NOT_RUN;
		}
		if ( !( e->info & ( ENT_CORPSE | ENT_REMOVED ) ) ) {
			if ( opts & 2 ) {
				return SCRIPT_ABORT;
			}
			break;
		}
		there = Game_findEntityAt( game, x + 32, y + 32, 0x406 );
		if ( there && !( there->def->eType == ETYPE_MONSTER && there->def->eSubType == 0xe ) ) {
			return ( opts & 2 ) ? SCRIPT_ABORT : SCRIPT_DONE;
		}
		Entity_resurrect( e, x + 32, y + 32, 0x20 );
		if ( opts & 1 ) {
			e->info |= ENT_AGGRO;
			Game_activateEx( game, e, 1, 0 );
		}
		break;
	}

	case 0x6f:		/* EV_SET: player flag b0 & 0x1f set (arg >> 5 not 0) or cleared */
		CALLING( "EV_SET" );
		if ( ( arg >> 5 ) == 0 ) {
			player->flags &= ~( 1u << ( arg & 0x1f ) );
		} else {
			player->flags |= 1u << ( arg & 0x1f );
		}
		break;

	case 0x70: {	/* EV_TRIGGERIF: the event of tile b0, b1 runs nested if player flag b2 & 0x1f is set
					 * (bit 21) or clear */
		int want = ( arg >> 21 ) & 1, has = ( player->flags >> ( ( arg >> 16 ) & 0x1f ) ) & 1;
		CALLING( "EV_TRIGGERIF" );
		if ( want == has ) {
			u8 ff = frame->frameFlags;
			frame->frameFlags = ff | FRAME_NO_RESUME;
			r = ScriptThread_executeTile( self, B0, B1, (int)( flags & 0x2000000 ) | 0xf000, ff & FRAME_NESTED );
			frame->frameFlags &= ~FRAME_NO_RESUME;
			if ( r == SCRIPT_PAUSED ) {
				return SCRIPT_PAUSED;
			}
		}
		break;
	}

	case 0x71: {	/* EV_LERPSPRITETOOPENTILE: sprite (arg >> 7) & 0x3ff moves to a free tile next to it in
					 * (arg & 0x7f) * 100 ms, the thread waiting; nothing if there is none */
		int		spr = (int)( ( arg >> 7 ) & 0x3ff ), tile, ox, oy, open, result = SCRIPT_DONE;
		Sprite	*s = &render->sprites[spr];
		Entity	*saved;
		CALLING( "EV_LERPSPRITETOOPENTILE" );
		tile = ( s->y >> 6 ) * MAP_TILES + ( s->x >> 6 );
		saved = game->tileLists[tile];		/* (its own tile is left out) */
		game->tileLists[tile] = NULL;
		open = Entity_findOpenAdjacentTile( s->x, s->y, -1, &ox, &oy, s->ent );
		game->tileLists[tile] = saved;
		if ( open ) {
			LerpSprite *ls = Game_allocLerpSprite( game, self, spr );
			if ( ls ) {
				ls->dstX = (s16)ox;
				ls->dstY = (s16)oy;
				ls->dstZ = s->z;
				if ( s->ent ) {
					s->ent->info = ( s->ent->info & ~ENT_LERPING ) | 0x88000000;
					if ( s->ent->monster ) {
						s->ent->monster->destX = ls->dstX;
						s->ent->monster->destY = ls->dstY;
					}
				}
				ls->srcX = s->x;
				ls->srcY = s->y;
				ls->srcZ = s->z;
				ls->param = s->param;
				ls->dstScale = ls->srcScale = s->scale;
				ls->startTime = app->gameTime;
				ls->duration = (int)( arg & 0x7f ) * 100;
				{
					int dx = ls->dstX - ls->srcX, dy = ls->dstY - ls->srcY;
					ls->dist = (s16)FixedSqrt( (u64)( ( dx * dx + dy * dy ) * 0x100 ) );
				}
				if ( s->ent ) {
					/* the entity is on its new tile at once */
					ls->flags = LERP_RELINKED;
					Game_unlinkEntity( game, s->ent );
					Game_linkEntity( game, s->ent, ox >> 6, oy >> 6 );
					Canvas_updateFacing( canvas );
				}
				game->yieldFlag = 1;
				result = SCRIPT_PAUSED;
			}
		}
		return result;
	}

	case 0x72: {	/* EV_ABORTUNLESSTILEOPEN: the event stops if tile b0 & 0x1f, (arg >> 5) & 0x1f is taken;
					 * with bit 18, if no tile next to it is free */
		int tx = (int)( arg & 0x1f ), ty = (int)( ( arg >> 5 ) & 0x1f ), result = SCRIPT_DONE;
		CALLING( "EV_ABORTUNLESSTILEOPEN" );
		if ( !( arg & 0x40000 ) ) {
			Game_trace( game, TILE_CENTER( tx ), TILE_CENTER( ty ), TILE_CENTER( tx ), TILE_CENTER( ty ), NULL, 0xfdaf );
			if ( game->numTraceHits ) {
				result = SCRIPT_ABORT;
			}
		} else {
			int tile = tx + ty * MAP_TILES, ox, oy;
			Entity *saved = game->tileLists[tile];
			game->tileLists[tile] = NULL;
			if ( !Entity_findOpenAdjacentTile( TILE_CENTER( tx ), TILE_CENTER( ty ), -1, &ox, &oy, NULL ) ) {
				result = SCRIPT_ABORT;
			}
			game->tileLists[tile] = saved;
		}
		return result;
	}

	case 0x73:		/* (no name) entry lo16 of the player's list gets state b2 */
		Player_setListState( player, (int)( arg & 0xffff ), B2 );
		break;

	case 0x74:		/* (no name) the map's ambient sound b0 on (bit 16) or off */
		Sound_setEmitter( sound, ( sound->firstMapEmitter + (int)B0 ) & 0xff, ( arg & 0x10000 ) != 0 );
		break;

	case 0x75:		/* (no name) the player gets collectible arg - 1 (of 15) */
		player->collectibles |= 1u << ( ( arg - 1 ) & 0xff );
		Player_countCollectibles( player );
		app->menuSystem->lastCollectible = (u16)( arg - 1 );
		break;

	default:		/* 0, 0x27, 0x2b, 0x2f, 0x38, 0x39, 0x3b, 0x4d, 0x68 and beyond 0x77 */
		App_fatal( app, "unhandled script event %d param %d flags %d", op, arg, flags );
		break;
	}
	return SCRIPT_DONE;
}

#undef B0
#undef B1
#undef B2
#undef B3
#undef CALLING

/* 0x02052710 (0x34 bytes) ScriptThread_checkWait (Ghidra: FUN_02052710)
 * file: name */
/* The thread waiting (EV_WAIT) runs on once its time has come; 1 if it did */
int ScriptThread_checkWait( ScriptThread *self, int now ) {
	if ( self->waitUntil == 0 || now < self->waitUntil ) {
		return 0;
	}
	self->waitUntil = 0;
	ScriptThread_run( self );
	return 1;
}

/* 0x02052744 (0xb0 bytes) ScriptThread_saveState (Ghidra: FUN_02052744)
 * file: name */
/* The thread into a save: the time left to wait, its state and its frames */
void ScriptThread_saveState( ScriptThread *self, OutputStream *os ) {
	int i;

	OutStream_writeInt( os, self->waitUntil ? self->waitUntil - self->app->time : 0 );
	OutStream_writeByte( os, self->state );
	OutStream_writeByte( os, self->numFrames );
	for ( i = 0; i < self->numFrames; i++ ) {
		ScriptFrame *f = &self->frames[i];
		OutStream_writeInt( os, (int)f->event );
		OutStream_writeInt( os, (int)f->flags );
		OutStream_writeByte( os, (s8)f->cmdIndex );
		OutStream_writeByte( os, (s8)f->frameFlags );
	}
}

/* 0x020527f4 (0x100 bytes) ScriptThread_loadState (Ghidra: FUN_020527f4)
 * file: name */
/* The thread from a save (ScriptThread_saveState): read into the stream's buffer 6 bytes, then
 * 10 a frame */
void ScriptThread_loadState( ScriptThread *self, InputStream *is ) {
	int i;

	ScriptThread_init( self );
	InputStream_fill( is, 6 );
	self->waitUntil = InputStream_readInt( is );
	if ( self->waitUntil ) {
		self->waitUntil += self->app->time;
	}
	self->state = (s8)is->buffer[is->pos++];
	self->numFrames = (s8)is->buffer[is->pos++];
	InputStream_fill( is, (s16)self->numFrames * 10 );
	for ( i = 0; i < self->numFrames; i++ ) {
		ScriptFrame *f = &self->frames[i];
		f->event = (u32)InputStream_readInt( is );
		f->flags = (u32)InputStream_readInt( is );
		f->cmdIndex = is->buffer[is->pos++];
		f->frameFlags = is->buffer[is->pos++];
	}
}

/* 0x020528f4 (0x90 bytes) ScriptThread_signal (Ghidra: FUN_020528f4)
 * file: name */
/* What a paused thread's last frame waits on has happened (FRAME_COMBAT: the fight EV_AIGOAL
 * started is over): those flags are cleared and the thread runs on at the next check */
void ScriptThread_signal( ScriptThread *self, u32 frameFlags ) {
	ScriptFrame *top;

	if ( self->numFrames == 0 || self->state != SCRIPT_PAUSED ) {
		return;
	}
	top = &self->frames[self->numFrames - 1];
	if ( frameFlags != ( frameFlags & top->frameFlags ) ) {
		return;
	}
	self->waitUntil = NOW_MS() - 1;
	top->frameFlags &= ~frameFlags;
}

